import React, { useId } from 'react';

interface OfficialSchoolSealProps {
  schoolName: string;
  schoolCode: string;
  dateLabel?: string;
  statusLabel?: string;
}

/** Crisp auto-generated circular vector ink seal bearing school identity and verified date. */
export const OfficialSchoolSeal: React.FC<OfficialSchoolSealProps> = ({
  schoolName,
  schoolCode,
  dateLabel = 'VERIFIED',
  statusLabel = 'PAID • VERIFIED',
}) => {
  const ringId = useId();
  const shortSchool = (schoolName || 'EDZY CAMPUS')
    .toUpperCase()
    .replace(/[^A-Z0-9\s]/g, '')
    .slice(0, 26);

  const ringText = `${shortSchool} • ${schoolCode.toUpperCase()} • `;

  return (
    <svg
      viewBox="0 0 140 140"
      className="w-24 h-24 text-[#1E3A8A] select-none shrink-0"
      role="img"
      aria-label={`Official school seal for ${schoolName} (${schoolCode})`}
    >
      <defs>
        <path
          id={ringId}
          d="M 70,70 m -48,0 a 48,48 0 1,1 96,0 a 48,48 0 1,1 -96,0"
        />
      </defs>
      <circle cx="70" cy="70" r="64" fill="none" stroke="currentColor" strokeWidth="2.5" />
      <circle
        cx="70"
        cy="70"
        r="58"
        fill="none"
        stroke="currentColor"
        strokeWidth="1"
        strokeDasharray="3 2"
      />
      <circle cx="70" cy="70" r="34" fill="none" stroke="currentColor" strokeWidth="1.4" />
      <text
        fill="currentColor"
        fontSize="7.4"
        fontWeight="800"
        letterSpacing="1.35"
        fontFamily="ui-sans-serif, system-ui, sans-serif"
      >
        <textPath href={`#${ringId}`} startOffset="2%">
          {ringText}
        </textPath>
      </text>
      <text
        x="70"
        y="61"
        textAnchor="middle"
        fill="#059669"
        fontSize="8.5"
        fontWeight="900"
        letterSpacing="0.7"
        fontFamily="ui-monospace, monospace"
      >
        {statusLabel}
      </text>
      <text
        x="70"
        y="74"
        textAnchor="middle"
        fill="currentColor"
        fontSize="8"
        fontWeight="800"
        fontFamily="ui-monospace, monospace"
      >
        {dateLabel}
      </text>
      <text
        x="70"
        y="86"
        textAnchor="middle"
        fill="currentColor"
        fontSize="6.5"
        fontWeight="700"
        letterSpacing="0.8"
      >
        ACCOUNTS DESK
      </text>
    </svg>
  );
};

interface ReceiptStampSignoffBlockProps {
  schoolName: string;
  schoolCode: string;
  signatoryLabel: string;
  signatoryName: string;
  dateLabel?: string;
  stampDataUrl?: string | null;
  signatureDataUrl?: string | null;
  useAutoGeneratedSeal?: boolean;
  stampBlendMode?: boolean;
  isPaid?: boolean;
}

/** Shared stamp + signature footer used identically on ReceiptModal and SettingsPage live preview. */
export const ReceiptStampSignoffBlock: React.FC<ReceiptStampSignoffBlockProps> = ({
  schoolName,
  schoolCode,
  signatoryLabel,
  signatoryName,
  dateLabel = 'VERIFIED',
  stampDataUrl,
  signatureDataUrl,
  useAutoGeneratedSeal = true,
  stampBlendMode = true,
  isPaid = true,
}) => {
  return (
    <div className="flex items-end justify-end gap-5 flex-wrap">
      {/* Official School Stamp / Seal */}
      <div className="flex items-center justify-center">
        {stampDataUrl ? (
          <img
            src={stampDataUrl}
            alt={`${schoolName} official seal`}
            className={`w-24 h-24 object-contain -rotate-6 select-none ${
              stampBlendMode ? 'mix-blend-multiply' : ''
            }`}
          />
        ) : useAutoGeneratedSeal ? (
          <div className="-rotate-6">
            <OfficialSchoolSeal
              schoolName={schoolName}
              schoolCode={schoolCode}
              dateLabel={dateLabel}
              statusLabel={isPaid ? 'PAID • VERIFIED' : 'FEE DEMAND'}
            />
          </div>
        ) : null}
      </div>

      {/* Authorized Signatory Line */}
      <div className="text-right min-w-[175px]">
        <div className="h-12 flex items-end justify-end pb-1">
          {signatureDataUrl ? (
            <img
              src={signatureDataUrl}
              alt="Authorized signature"
              className="max-h-11 max-w-[160px] object-contain mix-blend-multiply"
            />
          ) : (
            <span className="text-sm font-serif italic text-slate-700 px-2">
              {signatoryName}
            </span>
          )}
        </div>
        <div className="border-t border-slate-500 pt-1">
          <p className="text-[11px] font-bold text-slate-900 leading-tight">{signatoryLabel}</p>
          <p className="text-[10px] text-slate-500">{schoolName}</p>
        </div>
      </div>
    </div>
  );
};
